import{_ as l,a0 as d,w as o,s as c,ao as t,I as p,x as a,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"Linux 上静态链接库工作原理 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 上静态链接库工作原理 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 上静态链接库工作原理 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 上静态链接库工作原理 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220603 How static linking works on Linux","title":"Linux 上静态链接库工作原理","tag":"202207","desc":""},"relativePath":"202207/20220603 How static linking works on Linux.md","filePath":"[post].md"}'),r={name:"202207/20220603 How static linking works on Linux.md"};function h(u,s,b,g,k,m){const n=d("Link");return o(),c("div",null,[s[21]||(s[21]=t('<h1 id="linux-上静态链接库工作原理" tabindex="-1">Linux 上静态链接库工作原理 <a class="header-anchor" href="#linux-上静态链接库工作原理" aria-label="Permalink to “Linux 上静态链接库工作原理”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202207/12/120441y0q5a5abfyjyy7ug.jpg" alt=""></p><blockquote><p>学习如何用静态链接库将多个 C 目标文件结合到一个单个的可执行文件之中。</p></blockquote><p>使用 C 编写的应用程序时，通常有多个源码文件，但最终你需要编译成单个的可执行文件。</p><p>你可以通过两种方式来完成这项工作：通过创建一个 <ruby>静态<rt>static</rt></ruby> 库 或 一个 <ruby>动态<rt>dynamic</rt></ruby> 库（也被称为 <ruby>共享<rt>shared</rt></ruby> 库）。从创建和链接的方式来看，它们是两种不同类型的库。选择使用哪种方式取决于你的的具体场景。</p>',5)),p("p",null,[s[1]||(s[1]=a("在 ",-1)),i(n,{href:"https://linux.cn/article-14813-1.html"},{default:e(()=>[...s[0]||(s[0]=[a("上一篇文章",-1)])]),_:1}),s[2]||(s[2]=a(" 中，我演示了如何创建一个动态链接的可执行文件，这是一种更通用的方法。在这篇文章中，我将说明如何创建一个静态链接的可执行文件。",-1))]),s[22]||(s[22]=t(`<h3 id="使用静态库链接器" tabindex="-1">使用静态库链接器 <a class="header-anchor" href="#使用静态库链接器" aria-label="Permalink to “使用静态库链接器”">​</a></h3><p><ruby>链接器<rt>linker</rt></ruby>是一个命令，它将一个程序的多个部分结合在一起，并为它们重新组织内存分配。</p><p>链接器的功能包括：</p><ul><li>整合一个程序的所有的部分</li><li>计算出一个新的内存组织结构，以便所有的部分组合在一起</li><li>恢复内存地址，以便程序可以在新的内存组织结构下运行</li><li>解析符号引用</li></ul><p>链接器通过这些功能，创建了一个名称为可执行文件的一个可运行程序。</p><p>静态库是通过复制一个程序中的所有依赖库模块到最终的可执行镜像来创建的。链接器将链接静态库作为编译过程的最后一步。可执行文件是通过解析外部引用、将库例程与程序代码结合在一起来创建的。</p><h3 id="创建目标文件" tabindex="-1">创建目标文件 <a class="header-anchor" href="#创建目标文件" aria-label="Permalink to “创建目标文件”">​</a></h3><p>这里是一个静态库的示例以及其链接过程。首先，创建带有这些函数识别标志的头文件 <code>mymath.h</code> :</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int add(int a, int b);</span></span>
<span class="line"><span>int sub(int a, int b);</span></span>
<span class="line"><span>int mult(int a, int b);</span></span>
<span class="line"><span>int divi(int a, int b);</span></span></code></pre></div><p>使用这些函数定义来创建 <code>add.c</code> 、<code>sub.c</code> 、<code>mult.c</code> 和 <code>divi.c</code> 文件。我将把所有的代码都放置到一个代码块中，请将其分为四个文件，如注释所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// add.c</span></span>
<span class="line"><span>int add(int a, int b){</span></span>
<span class="line"><span>return (a+b);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//sub.c</span></span>
<span class="line"><span>int sub(int a, int b){</span></span>
<span class="line"><span>return (a-b);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//mult.c</span></span>
<span class="line"><span>int mult(int a, int b){</span></span>
<span class="line"><span>return (a*b);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//divi.c</span></span>
<span class="line"><span>int divi(int a, int b){</span></span>
<span class="line"><span>return (a/b);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>现在，使用 GCC 来生成目标文件 <code>add.o</code> 、<code>sub.o</code> 、<code>mult.o</code> 和 <code>divi.o</code>：</p><p>（LCTT 校注：关于“<ruby>目标文件<rt>object file</rt></ruby>”，有时候也被称作“对象文件”，对此，存在一些译法混乱情形，称之为“目标文件”的译法比较流行，本文采用此译法。）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -c add.c sub.c mult.c divi.c</span></span></code></pre></div><p><code>-c</code> 选项跳过链接步骤，而只创建目标文件。</p><p>创建一个名称为 <code>libmymath.a</code> 的静态库，接下来，移除目标文件，因为它们不再被需要。（注意，使用一个 <code>trash</code> 命令比使用一个 <code>rm</code> 命令更安全。）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ar rs libmymath.a add.o sub.o mult.o divi.o</span></span>
<span class="line"><span>$ trash *.o</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>add.c  divi.c  libmymath.a  mult.c  mymath.h  sub.c</span></span></code></pre></div><p>现在，你已经创建了一个名称为 <code>libmymath</code> 的简单数学示例库，你可以在 C 代码中使用它。当然，也有非常复杂的 C 库，这就是他们这些开发者来生成最终产品的工艺流程，你和我可以安装这些库并在 C 代码中使用。</p><p>接下来，在一些自定义代码中使用你的数学库，然后链接它。</p><h3 id="创建一个静态链接的应用程序" tabindex="-1">创建一个静态链接的应用程序 <a class="header-anchor" href="#创建一个静态链接的应用程序" aria-label="Permalink to “创建一个静态链接的应用程序”">​</a></h3><p>假设你已经为数学运算编写了一个命令。创建一个名称为 <code>mathDemo.c</code> 的文件，并将这些代码复制粘贴至其中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;mymath.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  int x, y;</span></span>
<span class="line"><span>  printf(&quot;Enter two numbers\\n&quot;);</span></span>
<span class="line"><span>  scanf(&quot;%d%d&quot;,&amp;x,&amp;y);</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>  printf(&quot;\\n%d + %d = %d&quot;, x, y, add(x, y));</span></span>
<span class="line"><span>  printf(&quot;\\n%d - %d = %d&quot;, x, y, sub(x, y));</span></span>
<span class="line"><span>  printf(&quot;\\n%d * %d = %d&quot;, x, y, mult(x, y));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  if(y==0){</span></span>
<span class="line"><span>    printf(&quot;\\nDenominator is zero so can&#39;t perform division\\n&quot;);</span></span>
<span class="line"><span>      exit(0);</span></span>
<span class="line"><span>  }else{</span></span>
<span class="line"><span>      printf(&quot;\\n%d / %d = %d\\n&quot;, x, y, divi(x, y));</span></span>
<span class="line"><span>      return 0;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>注意：第一行是一个 <code>include</code> 语句，通过名称来引用你自己的 <code>libmymath</code> 库。</p><p>针对 <code>mathDemo.c</code> 创建一个名称为 <code>mathDemo.o</code> 的对象文件:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -I . -c mathDemo.c</span></span></code></pre></div><p><code>-I</code> 选项告诉 GCC 搜索在其后列出的头文件。在这个实例中，你通过单个点（<code>.</code>）来指定当前目录。</p><p>链接 <code>mathDemo.o</code> 和 <code>libmymath.a</code> 来生成最终的可执行文件。这里有两种方法来向 GCC 告知这一点。</p><p>你可以指向文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -static -o mathDemo mathDemo.o libmymath.a</span></span></code></pre></div><p>或者，你可以具体指定库的路径及名称：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -static -o mathDemo -L . mathDemo.o -lmymath</span></span></code></pre></div><p>在后面的那个示例中，<code>-lmymath</code> 选项告诉链接器来链接对象文件 <code>mathDemo.o</code> 和对象文件 <code>libmymath.a</code> 来生成最终的可执行文件。<code>-L</code> 选项指示链接器在下面的参数中查找库（类似于你使用 <code>-I</code> 所做的工作）。</p><h3 id="分析结果" tabindex="-1">分析结果 <a class="header-anchor" href="#分析结果" aria-label="Permalink to “分析结果”">​</a></h3><p>使用 <code>file</code> 命令来验证它是静态链接的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file mathDemo</span></span>
<span class="line"><span>mathDemo: ELF 64-bit LSB executable, x86-64...</span></span>
<span class="line"><span>statically linked, with debug_info, not stripped</span></span></code></pre></div><p>使用 <code>ldd</code> 命令，你将会看到该可执行文件不是动态链接的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ldd ./mathDemo</span></span>
<span class="line"><span>        not a dynamic executable</span></span></code></pre></div><p>你也可以查看 <code>mathDemo</code> 可执行文件的大小：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ du -h ./mathDemo</span></span>
<span class="line"><span>932K    ./mathDemo</span></span></code></pre></div>`,39)),p("p",null,[s[4]||(s[4]=a("在我 ",-1)),i(n,{href:"https://linux.cn/article-14813-1.html"},{default:e(()=>[...s[3]||(s[3]=[a("前一篇文章",-1)])]),_:1}),s[5]||(s[5]=a(" 的示例中，动态链接的可执行文件只占有 24K 大小。",-1))]),s[23]||(s[23]=t(`<p>运行该命令来看看它的工作内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./mathDemo</span></span>
<span class="line"><span>Enter two numbers</span></span>
<span class="line"><span>10</span></span>
<span class="line"><span>5</span></span>
<span class="line"><span></span></span>
<span class="line"><span>10 + 5 = 15</span></span>
<span class="line"><span>10 - 5 = 5</span></span>
<span class="line"><span>10 * 5 = 50</span></span>
<span class="line"><span>10 / 5 = 2</span></span></code></pre></div><p>看起来令人满意！</p><h3 id="何时使用静态链接" tabindex="-1">何时使用静态链接 <a class="header-anchor" href="#何时使用静态链接" aria-label="Permalink to “何时使用静态链接”">​</a></h3><p>动态链接可执行文件通常优于静态链接可执行文件，因为动态链接会保持应用程序的组件模块化。假如一个库接收到一次关键安全更新，那么它可以很容易地修补，因为它存在于应用程序的外部。</p><p>当你使用静态链接时，库的代码会“隐藏”在你创建的可执行文件之中，意味着在库每次更新时（相信我，你会有更好的东西），仅有的一种修补方法是重新编译和发布一个新的可执行文件。</p><p>不过，如果一个库的代码，要么存在于它正在使用的具有相同代码的可执行文件中，要么存在于不会接收到任何更新的专用嵌入式设备中，那么静态连接将是一种可接受的选项。</p><hr>`,8)),p("p",null,[s[7]||(s[7]=a("via: ",-1)),i(n,{href:"https://opensource.com/article/22/6/static-linking-linux"},{default:e(()=>[...s[6]||(s[6]=[a("https://opensource.com/article/22/6/static-linking-linux",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("作者：",-1)),i(n,{href:"https://opensource.com/users/jayashree-huttanagoudar"},{default:e(()=>[...s[8]||(s[8]=[a("Jayashree Huttanagoudar",-1)])]),_:1}),s[13]||(s[13]=a(" 选题：",-1)),i(n,{href:"https://github.com/lkxed"},{default:e(()=>[...s[9]||(s[9]=[a("lkxed",-1)])]),_:1}),s[14]||(s[14]=a(" 译者：",-1)),i(n,{href:"https://github.com/robsean"},{default:e(()=>[...s[10]||(s[10]=[a("robsean",-1)])]),_:1}),s[15]||(s[15]=a(" 校对：",-1)),i(n,{href:"https://github.com/turbokernel"},{default:e(()=>[...s[11]||(s[11]=[a("turbokernel",-1)])]),_:1})]),p("p",null,[s[18]||(s[18]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[16]||(s[16]=[a("LCTT",-1)])]),_:1}),s[19]||(s[19]=a(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[17]||(s[17]=[a("Linux中国",-1)])]),_:1}),s[20]||(s[20]=a(" 荣誉推出",-1))])])}const C=l(r,[["render",h]]);export{x as __pageData,C as default};
